import React, { useState } from 'react';

function WeekView({ date, entries, setEntries }) {
  const [isEditing, setIsEditing] = useState(false);
  const [selectedDay, setSelectedDay] = useState(null);
  const [selectedPeriod, setSelectedPeriod] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedPractice, setSelectedPractice] = useState('');
  const [selectedDuration, setSelectedDuration] = useState('30 мин');
  const [repeatInterval, setRepeatInterval] = useState('');

  const categories = [
    {
      name: 'Yoga',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Boxing',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'SoftDev',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'MBA',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'English',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Oratory',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Math',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Chinise',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Finance',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Chess',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Business',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    }
  ];

  const timeOptions = [
    '5 мин', '10 мин', '15 мин', '30 мин', '31 мин',
    '60 мин', '90 мин', '120 мин', '180 мин'
  ];

  const repeatOptions = [
    'Не повторять',
    'Каждый день',
    'Каждую неделю',
    'Каждый месяц',
    'Каждый год'
  ];

  const getWeekDays = () => {
    const week = [];
    const current = new Date(date);
    const day = current.getDay() || 7;
    current.setDate(current.getDate() - day + 1);

    for (let i = 0; i < 7; i++) {
      week.push(new Date(current));
      current.setDate(current.getDate() + 1);
    }

    return week;
  };

  const weekDays = getWeekDays();
  const dayNames = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
  const monthNames = ['янв', 'фев', 'мар', 'апр', 'май', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

  const timePeriods = [
    { id: 'morning', timeRange: '06:00 - 12:00', period: 'утро' },
    { id: 'day', timeRange: '12:00 - 18:00', period: 'день' },
    { id: 'evening', timeRange: '18:00 - 00:00', period: 'вечер' }
  ];

  const getDayEntries = (date) => {
    const dateKey = date.toDateString();
    const dayEntry = entries[dateKey];

    if (!dayEntry) return { morning: [], day: [], evening: [] };

    return {
      morning: dayEntry.morning || [],
      day: dayEntry.day || [],
      evening: dayEntry.evening || []
    };
  };

  const getCategoryColor = (category) => {
    const colors = {
      'Yoga': '#ff6b6b',
      'Boxing': '#4ecdc4',
      'SoftDev': '#45b7d1',
      'MBA': '#96ceb4',
      'English': '#ffeaa7',
      'Oratory': '#ff9ff3',
      'Math': '#feca57',
      'Chinise': '#ffb8b8',
      'Finance': '#c56cf0',
      'Chess': '#ffcccc',
      'Business': '#a8e6cf'
    };
    return colors[category] || '#ddd';
  };

  const getCurrentCategory = () => {
    return categories.find(c => c.name === selectedCategory);
  };

  const formatDate = (date) => {
    return `${date.getDate()} ${monthNames[date.getMonth()]}`;
  };

  const isToday = (date) => {
    const today = new Date();
    return date.toDateString() === today.toDateString();
  };

  const handlePrevWeek = () => {
    const prevWeek = new Date(date);
    prevWeek.setDate(date.getDate() - 7);
    window.location.reload();
  };

  const handleNextWeek = () => {
    const nextWeek = new Date(date);
    nextWeek.setDate(date.getDate() + 7);
    window.location.reload();
  };

  const handleToday = () => {
    window.location.reload();
  };

  const handleSlotClick = (day, periodId) => {
    setSelectedDay(day);
    setSelectedPeriod(periodId);
    setIsEditing(true);
  };

  const addItem = () => {
    if (selectedCategory && selectedPractice && selectedDay && selectedPeriod) {
      const dateKey = selectedDay.toDateString();
      const period = selectedPeriod;

      const newItem = {
        id: Date.now(),
        category: selectedCategory,
        practice: selectedPractice,
        duration: selectedDuration,
        repeat: repeatInterval,
        period: period,
        date: dateKey
      };

      // Если есть повтор, создаем записи для будущих дней
      if (repeatInterval && repeatInterval !== 'Не повторять') {
        const futureEntries = generateFutureEntries(selectedDay, newItem);

        setEntries(prev => ({
          ...prev,
          ...futureEntries,
          [dateKey]: {
            ...prev[dateKey],
            [period]: [...(prev[dateKey]?.[period] || []), newItem]
          }
        }));
      } else {
        setEntries(prev => ({
          ...prev,
          [dateKey]: {
            ...prev[dateKey],
            [period]: [...(prev[dateKey]?.[period] || []), newItem]
          }
        }));
      }

      // Сброс формы
      setSelectedCategory('');
      setSelectedPractice('');
      setSelectedDuration('30 мин');
      setRepeatInterval('');
      setIsEditing(false);
      setSelectedDay(null);
      setSelectedPeriod(null);
    }
  };

  const generateFutureEntries = (startDate, entry) => {
    const futureEntries = {};
    const maxFutureDays = 30;

    for (let i = 1; i <= maxFutureDays; i++) {
      const nextDate = new Date(startDate);

      switch(entry.repeat) {
        case 'Каждый день':
          nextDate.setDate(startDate.getDate() + i);
          break;
        case 'Каждую неделю':
          nextDate.setDate(startDate.getDate() + (i * 7));
          break;
        case 'Каждый месяц':
          nextDate.setMonth(startDate.getMonth() + i);
          break;
        case 'Каждый год':
          nextDate.setFullYear(startDate.getFullYear() + i);
          break;
        default:
          continue;
      }

      const nextDateKey = nextDate.toDateString();

      const futureEntry = {
        ...entry,
        id: Date.now() + i,
        date: nextDateKey,
        originalDate: startDate.toDateString()
      };

      if (!futureEntries[nextDateKey]) {
        futureEntries[nextDateKey] = { morning: [], day: [], evening: [] };
      }

      futureEntries[nextDateKey][entry.period].push(futureEntry);
    }

    return futureEntries;
  };

  const removeItem = (dateKey, period, itemId) => {
    setEntries(prev => {
      const newEntries = { ...prev };
      if (newEntries[dateKey] && newEntries[dateKey][period]) {
        newEntries[dateKey][period] = newEntries[dateKey][period].filter(
          item => item.id !== itemId
        );
      }
      return newEntries;
    });
  };

  return (
    <div className="week-view">
      <div className="week-navigation">
        <button onClick={handlePrevWeek} className="nav-btn">←</button>
        <div className="week-title">
          <h2>
            Неделя {formatDate(weekDays[0])} - {formatDate(weekDays[6])}
          </h2>
          <button onClick={handleToday} className="today-btn">
            Сегодня
          </button>
        </div>
        <button onClick={handleNextWeek} className="nav-btn">→</button>
      </div>

      <div className="week-schedule">
        {/* Левая колонка с временными промежутками */}
        <div className="week-time-labels">
          <div className="time-labels-header">Время</div>
          {timePeriods.map(period => (
            <div key={period.id} className={`time-label ${period.id}-label`}>
              {period.timeRange}
            </div>
          ))}
        </div>

        {/* Колонки дней недели */}
        {weekDays.map((day, dayIndex) => {
          const dayEntries = getDayEntries(day);
          const isCurrentDay = isToday(day);

          return (
            <div key={dayIndex} className={`week-day-column ${isCurrentDay ? 'today' : ''}`}>
              <div className="week-day-header">
                <div className="day-name">{dayNames[dayIndex]}</div>
                <div className="day-date">{formatDate(day)}</div>
              </div>

              <div className="week-periods">
                {/* Утро */}
                <div
                  className="week-period morning-period"
                  onClick={() => handleSlotClick(day, 'morning')}
                >
                  {dayEntries.morning.map(entry => (
                    <div
                      key={entry.id}
                      className="week-entry"
                      style={{ backgroundColor: getCategoryColor(entry.category) }}
                      onClick={(e) => {
                        e.stopPropagation();
                        if (window.confirm('Удалить запись?')) {
                          removeItem(day.toDateString(), 'morning', entry.id);
                        }
                      }}
                    >
                      <div className="entry-category">{entry.category}</div>
                      <div className="entry-practice">{entry.practice}</div>
                      <div className="entry-duration">⏱️ {entry.duration}</div>
                      {entry.repeat && entry.repeat !== 'Не повторять' && (
                        <div className="entry-repeat">🔄</div>
                      )}
                    </div>
                  ))}
                  {dayEntries.morning.length === 0 && (
                    <div className="empty-slot">+</div>
                  )}
                </div>

                {/* День */}
                <div
                  className="week-period day-period"
                  onClick={() => handleSlotClick(day, 'day')}
                >
                  {dayEntries.day.map(entry => (
                    <div
                      key={entry.id}
                      className="week-entry"
                      style={{ backgroundColor: getCategoryColor(entry.category) }}
                      onClick={(e) => {
                        e.stopPropagation();
                        if (window.confirm('Удалить запись?')) {
                          removeItem(day.toDateString(), 'day', entry.id);
                        }
                      }}
                    >
                      <div className="entry-category">{entry.category}</div>
                      <div className="entry-practice">{entry.practice}</div>
                      <div className="entry-duration">⏱️ {entry.duration}</div>
                      {entry.repeat && entry.repeat !== 'Не повторять' && (
                        <div className="entry-repeat">🔄</div>
                      )}
                    </div>
                  ))}
                  {dayEntries.day.length === 0 && (
                    <div className="empty-slot">+</div>
                  )}
                </div>

                {/* Вечер */}
                <div
                  className="week-period evening-period"
                  onClick={() => handleSlotClick(day, 'evening')}
                >
                  {dayEntries.evening.map(entry => (
                    <div
                      key={entry.id}
                      className="week-entry"
                      style={{ backgroundColor: getCategoryColor(entry.category) }}
                      onClick={(e) => {
                        e.stopPropagation();
                        if (window.confirm('Удалить запись?')) {
                          removeItem(day.toDateString(), 'evening', entry.id);
                        }
                      }}
                    >
                      <div className="entry-category">{entry.category}</div>
                      <div className="entry-practice">{entry.practice}</div>
                      <div className="entry-duration">⏱️ {entry.duration}</div>
                      {entry.repeat && entry.repeat !== 'Не повторять' && (
                        <div className="entry-repeat">🔄</div>
                      )}
                    </div>
                  ))}
                  {dayEntries.evening.length === 0 && (
                    <div className="empty-slot">+</div>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Модальное окно для добавления события */}
      {isEditing && (
        <div className="modal-overlay" onClick={() => {
          setIsEditing(false);
          setSelectedDay(null);
          setSelectedPeriod(null);
        }}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>Добавить событие</h3>
            <div className="selected-info">
              {selectedDay && (
                <p>
                  {selectedDay.toLocaleDateString('ru-RU', {
                    weekday: 'long',
                    day: 'numeric',
                    month: 'long'
                  })}
                </p>
              )}
              {selectedPeriod && (
                <p className="period-info">
                  {selectedPeriod === 'morning' && '🌅 Утро (06:00 - 12:00)'}
                  {selectedPeriod === 'day' && '☀️ День (12:00 - 18:00)'}
                  {selectedPeriod === 'evening' && '🌙 Вечер (18:00 - 00:00)'}
                </p>
              )}
            </div>

            <div className="add-item-form">
              <select
                value={selectedCategory}
                onChange={(e) => {
                  setSelectedCategory(e.target.value);
                  setSelectedPractice('');
                }}
              >
                <option value="">Выберите категорию</option>
                {categories.map(cat => (
                  <option key={cat.name} value={cat.name}>{cat.name}</option>
                ))}
              </select>

              {selectedCategory && (
                <select
                  value={selectedPractice}
                  onChange={(e) => setSelectedPractice(e.target.value)}
                >
                  <option value="">Выберите практику</option>
                  {getCurrentCategory()?.practices.map(practice => (
                    <option key={practice} value={practice}>{practice}</option>
                  ))}
                </select>
              )}

              <select
                value={selectedDuration}
                onChange={(e) => setSelectedDuration(e.target.value)}
              >
                {timeOptions.map(time => (
                  <option key={time} value={time}>{time}</option>
                ))}
              </select>

              <select
                value={repeatInterval}
                onChange={(e) => setRepeatInterval(e.target.value)}
              >
                {repeatOptions.map(option => (
                  <option key={option} value={option}>{option}</option>
                ))}
              </select>

              <div className="form-actions">
                <button
                  onClick={addItem}
                  className="add-btn"
                  disabled={!selectedCategory || !selectedPractice}
                >
                  Добавить
                </button>
                <button
                  onClick={() => {
                    setIsEditing(false);
                    setSelectedDay(null);
                    setSelectedPeriod(null);
                  }}
                  className="cancel-btn"
                >
                  Отмена
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default WeekView;
